// test_refdata.cpp — validation against the frozen Python reference table
// (tests/refdata/core.json, generated by tests/gen_ref_tables.py).
//
// C++ port of internal/evalsig/refdata_test.go. Sections whose Python
// implementation is pure IEEE arithmetic, exact rational arithmetic, MT19937,
// or formatting are compared bit-for-bit (a == b). Sections that transit
// through libm transcendentals are compared with tolerance instead, and bit
// equality there is not a well-defined target: CPython delegates math.log /
// math.erf to the platform C runtime, and UCRT (Windows), glibc, and Go's
// fdlibm port each round differently. The tolerances follow the error
// structure:
//
//   - normInvCDF / zTwoSided: log feeds sqrt and a polynomial; its 1-2 ulp
//     error arrives as <= a few ulp of the final quantile -> fewUlpEq.
//   - tail p-values (two_prop, compare): p = 2*(1 - cdf) = 1 - erf(w), where
//     the subtraction is exact, so an erf error of a few ulp at magnitude <= 1
//     becomes an ABSOLUTE error <= ~1e-15 regardless of how small p is ->
//     pValueEq combines that absolute floor with the relative tolerance.

#include <cmath>
#include <chrono>
#include <cstdint>
#include <cstdio>
