// ---------------------------------------------------------------- intervals

void testWilson(const PyObj& t) {
    const auto& cases = casesOf(t, "wilson");
    for (size_t i = 0; i < cases.size(); i++) {
        const PyObj& c = caseObj(cases[i]);
        int s = static_cast<int>(intField(c, "s"));
        int n = static_cast<int>(intField(c, "n"));
        double alpha = numField(c, "alpha");
        double low = numField(c, "low");
        double high = numField(c, "high");
        double rootsLow = numField(c, "roots_low");
        double rootsHigh = numField(c, "roots_high");
        Interval w = wilsonInterval(s, n, alpha);
        if (!bitsEq(w.low, low) || !bitsEq(w.high, high)) {
            fail("wilson[" + fmtLL(i) + "] " + fmtLL(s) + "/" + fmtLL(n) + " a=" +
                 fdesc(alpha) + " low: got " + fdesc(w.low) + ", want " + fdesc(low) +
                 " (bits)");
            fail("wilson[" + fmtLL(i) + "] " + fmtLL(s) + "/" + fmtLL(n) + " a=" +
                 fdesc(alpha) + " high: got " + fdesc(w.high) + ", want " + fdesc(high) +
                 " (bits)");
        }
        Interval r = wilsonIntervalRoots(s, n, alpha);
        if (!bitsEq(r.low, rootsLow) || !bitsEq(r.high, rootsHigh)) {
            fail("wilsonRoots[" + fmtLL(i) + "] " + fmtLL(s) + "/" + fmtLL(n) + " a=" +
                 fdesc(alpha) + " low: got " + fdesc(r.low) + ", want " + fdesc(rootsLow) +
                 " (bits)");
            fail("wilsonRoots[" + fmtLL(i) + "] " + fmtLL(s) + "/" + fmtLL(n) + " a=" +
                 fdesc(alpha) + " high: got " + fdesc(r.high) + ", want " + fdesc(rootsHigh) +
                 " (bits)");
        }
    }
}

void testNewcombe(const PyObj& t) {
    const auto& cases = casesOf(t, "newcombe");
    for (size_t i = 0; i < cases.size(); i++) {
        const PyObj& c = caseObj(cases[i]);
        double p1 = numField(c, "p1");
        int n1 = static_cast<int>(intField(c, "n1"));
        double p2 = numField(c, "p2");
        int n2 = static_cast<int>(intField(c, "n2"));
        double alpha = numField(c, "alpha");
        double low = numField(c, "low");
        double high = numField(c, "high");
        Interval got = newcombeDiffInterval(p1, n1, p2, n2, alpha);
        if (!bitsEq(got.low, low) || !bitsEq(got.high, high)) {
            fail("newcombe[" + fmtLL(i) + "]: got low " + fdesc(got.low) + ", want " +
                 fdesc(low) + " (bits)");
            fail("newcombe[" + fmtLL(i) + "]: got high " + fdesc(got.high) + ", want " +
                 fdesc(high) + " (bits)");
        }
    }
}

void testTwoProportion(const PyObj& t) {
    const auto& cases = casesOf(t, "two_prop");
    for (size_t i = 0; i < cases.size(); i++) {
        const PyObj& c = caseObj(cases[i]);
        int s1 = static_cast<int>(intField(c, "s1"));
        int n1 = static_cast<int>(intField(c, "n1"));
        int s2 = static_cast<int>(intField(c, "s2"));
        int n2 = static_cast<int>(intField(c, "n2"));
        double alpha = numField(c, "alpha");
        double diff = numField(c, "diff");
        double low = numField(c, "low");
        double high = numField(c, "high");
        double z = flexField(c, "z");
        double p = flexField(c, "p");
        TwoPropResult r = twoProportionTest(s1, n1, s2, n2, alpha);
        if (!bitsEq(r.diff, diff)) {
            fail("twoProp[" + fmtLL(i) + "] diff: got " + fdesc(r.diff) + ", want " +
                 fdesc(diff) + " (bits)");
        }
        if (!bitsEq(r.ci.low, low) || !bitsEq(r.ci.high, high)) {
            fail("twoProp[" + fmtLL(i) + "] ci.low: got " + fdesc(r.ci.low) + ", want " +
                 fdesc(low) + " (bits)");
            fail("twoProp[" + fmtLL(i) + "] ci.high: got " + fdesc(r.ci.high) + ", want " +
                 fdesc(high) + " (bits)");
        }
        if (!bitsEq(r.z, z)) {
            fail("twoProp[" + fmtLL(i) + "] z: got " + fdesc(r.z) + ", want " + fdesc(z) +
                 " (bits)");
        }
        if (!pValueEq(r.pValue, p)) {
            fail("twoProp[" + fmtLL(i) + "] p: got " + fdesc(r.pValue) + ", want " + fdesc(p) +
                 " (ulp)");
        }
    }
}

